import csv, math, statistics
from collections import Counter, defaultdict

DATA='benchmark/data.csv'

def to_float(x):
    x=str(x).strip()
    if x=='': return None
    if x.startswith('.'):
        x='0'+x
    try:
        return float(x)
    except:
        return None

def classify(mm, ecc):
    if mm is None:
        return 'Unknown'
    if mm > 14:
        return 'LEO'
    if 0.99 <= mm <= 1.01:
        return 'GEO'
    if ecc is not None and ecc >= 0.2:
        return 'HEO'
    return 'MEO'

def prefix(name):
    s=str(name).strip().upper()
    if '-' in s:
        return s.split('-')[0]
    return s.split(' ')[0]

# regime by constellation prefix
reg_by_const=defaultdict(Counter)
const_total=Counter()

with open(DATA, newline='', encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        mm=to_float(row['MEAN_MOTION'])
        ecc=to_float(row['ECCENTRICITY'])
        reg=classify(mm,ecc)
        pre=prefix(row['OBJECT_NAME'])
        reg_by_const[pre][reg]+=1
        const_total[pre]+=1

for pre in ['STARLINK','ONEWEB','KUIPER','IRIDIUM','NAVSTAR','BEIDOU','QIANFAN','HULIANWANG DIGUI']:
    if pre in const_total:
        total=const_total[pre]
        regs=reg_by_const[pre]
        print(pre, total, dict(regs))
