import csv, json, math, statistics, datetime as dt
from collections import Counter, defaultdict

DATA='benchmark/data.csv'

# Helpers

def to_float(x):
    if x is None:
        return None
    s=str(x).strip()
    if s=='':
        return None
    if s.startswith('.'):
        s='0'+s
    try:
        return float(s)
    except:
        return None

def parse_year(object_id):
    if not object_id:
        return None
    s=str(object_id)
    if len(s) >= 4 and s[:4].isdigit():
        return int(s[:4])
    return None

def parse_epoch(s):
    try:
        return dt.datetime.fromisoformat(s)
    except:
        return None

# Regime cutoffs (mean motion rev/day)
LEO_MM_GT = 14.0
GEO_MM_MIN = 0.99
GEO_MM_MAX = 1.01
HEO_ECC_GE = 0.2

def classify(mm, ecc):
    if mm is None:
        return 'Unknown'
    if mm > LEO_MM_GT:
        return 'LEO'
    if GEO_MM_MIN <= mm <= GEO_MM_MAX:
        return 'GEO'
    if ecc is not None and ecc >= HEO_ECC_GE:
        return 'HEO'
    return 'MEO'

def prefix(name):
    s=str(name).strip().upper()
    if '-' in s:
        return s.split('-')[0]
    return s.split(' ')[0]

# Accumulators
n=0
mm=[]; inc=[]; ecc=[]
mm_nostar=[]; inc_nostar=[]; ecc_nostar=[]

starlink=0
leocount=0
since2020=0

epoch_min=None; epoch_max=None
reg_counts=Counter()
year_counts=Counter()
prefix_counts=Counter()
reg_by_prefix=defaultdict(Counter)

# Inclination distributions
bins_10 = [0]*18  # [0-10)...[170-180]

def bin10(deg):
    if deg is None:
        return None
    d=max(0.0, min(180.0, deg))
    i=int(d//10)
    if i==18: i=17
    return i

# Mean-motion shells histogram (for chart)
# Choose bins around LEO region: 0-1.5, 1.5-3, 3-8, 8-12, 12-14, 14-15, 15-16, 16-17, 17-18
mm_bins=[(0,1.5),(1.5,3),(3,8),(8,12),(12,14),(14,15),(15,16),(16,17),(17,18)]
mm_hist=[0]*len(mm_bins)

def mm_bin(v):
    for i,(a,b) in enumerate(mm_bins):
        if (v>=a and v<b) or (i==len(mm_bins)-1 and v>=a and v<=b):
            return i
    return None

# Top outliers
max_ecc = (-1,None)
min_mm = (1e9,None)
max_mm = (-1,None)

with open(DATA, newline='', encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        n+=1
        name=row['OBJECT_NAME']
        oid=row['OBJECT_ID']
        mm_v=to_float(row['MEAN_MOTION'])
        inc_v=to_float(row['INCLINATION'])
        ecc_v=to_float(row['ECCENTRICITY'])
        ep=parse_epoch(row['EPOCH'])

        if ep:
            epoch_min = ep if epoch_min is None else min(epoch_min, ep)
            epoch_max = ep if epoch_max is None else max(epoch_max, ep)

        if mm_v is not None:
            mm.append(mm_v)
            bi=mm_bin(mm_v)
            if bi is not None:
                mm_hist[bi]+=1
            if mm_v < min_mm[0]:
                min_mm=(mm_v,name)
            if mm_v > max_mm[0]:
                max_mm=(mm_v,name)
        if inc_v is not None:
            inc.append(inc_v)
            b=bin10(inc_v)
            if b is not None:
                bins_10[b]+=1
        if ecc_v is not None:
            ecc.append(ecc_v)
            if ecc_v > max_ecc[0]:
                max_ecc=(ecc_v,name)

        is_star = str(name).upper().startswith('STARLINK')
        if is_star:
            starlink += 1
        else:
            if mm_v is not None: mm_nostar.append(mm_v)
            if inc_v is not None: inc_nostar.append(inc_v)
            if ecc_v is not None: ecc_nostar.append(ecc_v)

        reg=classify(mm_v,ecc_v)
        reg_counts[reg]+=1
        if reg=='LEO':
            leocount += 1

        y=parse_year(oid)
        if y is not None:
            year_counts[y]+=1
            if y>=2020:
                since2020 += 1

        pre=prefix(name)
        prefix_counts[pre]+=1
        reg_by_prefix[pre][reg]+=1

# KPIs
median_inc = statistics.median(sorted(inc)) if inc else None
kpis={
    'Total Active Satellites': n,
    'LEO Share (%)': leocount/n*100 if n else None,
    'Starlink Constellation Size': starlink,
    'Median Inclination (degrees)': median_inc,
    'Satellites Launched Since 2020': since2020,
}

# Year series
years=sorted(year_counts)
y_counts=[year_counts[y] for y in years]
cum=[]
run=0
for c in y_counts:
    run+=c
    cum.append(run)

# Top constellations
TOP_N=12
largest=prefix_counts.most_common(TOP_N)

# Regime shares
reg_order=['LEO','MEO','GEO','HEO','Unknown']
reg_table=[{'regime':r,'count':reg_counts[r],'share_pct': (reg_counts[r]/n*100 if n else 0)} for r in reg_order if reg_counts[r]>0]

out={
    'epoch_min': epoch_min.isoformat() if epoch_min else None,
    'epoch_max': epoch_max.isoformat() if epoch_max else None,
    'kpis': kpis,
    'regime_cutoffs': {
        'LEO': f'MEAN_MOTION > {LEO_MM_GT}',
        'GEO': f'{GEO_MM_MIN} <= MEAN_MOTION <= {GEO_MM_MAX}',
        'HEO': f'ECCENTRICITY >= {HEO_ECC_GE} (applied when not LEO/GEO)',
        'MEO': 'all remaining satellites with MEAN_MOTION available',
    },
    'reg_table': reg_table,
    'years': years,
    'year_counts': y_counts,
    'year_cum': cum,
    'top_prefixes': [{'prefix':k,'count':v,'share_pct': v/n*100} for k,v in largest],
    'incl_bins_10': bins_10,
    'mm_bins': mm_bins,
    'mm_hist': mm_hist,
    'outliers': {
        'max_eccentricity': {'ecc': max_ecc[0], 'object_name': max_ecc[1]},
        'min_mean_motion': {'mean_motion': min_mm[0], 'object_name': min_mm[1]},
        'max_mean_motion': {'mean_motion': max_mm[0], 'object_name': max_mm[1]},
    },
    'starlink': {
        'count': starlink,
        'share_pct': starlink/n*100,
        'regimes': dict(reg_by_prefix['STARLINK']),
    },
    'non_starlink': {
        'count': n-starlink,
        'share_pct': (n-starlink)/n*100,
        'median_inclination': statistics.median(sorted(inc_nostar)) if inc_nostar else None,
    }
}
print(json.dumps(out, indent=2))
PY

